import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Module 7 · Verifiable certificates","description":"","frontmatter":{},"headers":[],"relativePath":"modules/07-verifiable-certificates.md","filePath":"modules/07-verifiable-certificates.md","lastUpdated":1790431304000}'),n={name:"modules/07-verifiable-certificates.md"};function r(o,e,h,l,d,c){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="module-7-·-verifiable-certificates" tabindex="-1">Module 7 · Verifiable certificates <a class="header-anchor" href="#module-7-·-verifiable-certificates" aria-label="Permalink to &quot;Module 7 · Verifiable certificates&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Contract</strong></td><td><code>CertificateRegistry.sol</code></td></tr><tr><td><strong>Stop</strong></td><td>College</td></tr><tr><td><strong>Model</strong></td><td>W3C Verifiable Credentials, simplified — hash anchoring</td></tr><tr><td><strong>Stamp</strong></td><td>Module 7 (awarded to the <strong>issuer</strong>)</td></tr></tbody></table><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>You have a degree certificate. An employer in another country wants to know it is real.</p><p>Today they email the university, wait, and hope someone answers — or they trust a PDF, which anyone can edit. Diploma fraud is a real industry, and the usual fix is to centralise verification with a company who charges for each check and becomes a new single point of failure.</p><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p><strong>The issuer signs, the holder keeps, the verifier checks.</strong></p><p>The university issues a certificate and anchors its <strong>hash</strong> on chain, along with who issued it, to whom, and when. The student keeps the document. Anyone holding the document can hash it and compare — no phone call, no fee, no permission.</p><p>The document itself never touches the chain. That is not an optimisation; a transcript is personal data and a public ledger is the worst possible place for it.</p><h2 id="key-terms" tabindex="-1">Key terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key terms&quot;">​</a></h2><p><strong>Verifiable credential.</strong> A claim made by an issuer about a subject, which a verifier can check without contacting the issuer. The W3C model has three roles — issuer, holder, verifier — and this module is a deliberately simplified version of it.</p><p><strong>Anchoring.</strong> Putting a hash on chain so that a document&#39;s existence at a point in time can be proven later. The chain becomes a timestamping and integrity service, nothing more.</p><p><strong>Revocation.</strong> Cancelling a credential after issuance. This is the genuinely hard part of every credential system, on chain or off, and the reason most academic designs quietly skip it.</p><p><strong>Selective disclosure.</strong> Proving one fact from a credential (&quot;I have a degree&quot;) without revealing the rest (&quot;in this subject, with these marks, from this year&quot;). Not solved here — it needs module 16&#39;s machinery.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Certificate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> issuer;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> holder;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    uint64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> issuedAt;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    uint64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> revokedAt;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 0 = valid</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> course;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    bytes32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> docHash;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">mapping</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes32</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> idOfDocument;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// hash → id</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Function</th><th>Who</th><th>What</th></tr></thead><tbody><tr><td><code>issue(holder, course, docHash)</code></td><td>any resident</td><td>Anchors the certificate</td></tr><tr><td><code>revoke(id, reason)</code></td><td>the issuer only</td><td>Marks it revoked, publicly, with a reason</td></tr><tr><td><code>verifyDocument(docHash)</code></td><td>anyone</td><td>&quot;Is this document anchored, and is it valid?&quot;</td></tr><tr><td><code>isValid(id)</code></td><td>anyone</td><td>Exists and not revoked</td></tr></tbody></table><p>The <code>idOfDocument</code> mapping is what makes verification one call: a verifier does not need to know the certificate id, only to possess the file. Hash it, look it up, done.</p><p>The contract refuses <code>SelfIssue()</code> — you cannot issue a certificate to yourself — and <code>DocumentAlreadyRegistered(id)</code>, so the same document cannot be anchored twice.</p><h2 id="the-detail-that-matters" tabindex="-1">The detail that matters <a class="header-anchor" href="#the-detail-that-matters" aria-label="Permalink to &quot;The detail that matters&quot;">​</a></h2><p><strong>Revocation cannot delete.</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c.revokedAt </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> uint64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">block</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.timestamp);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">emit</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CertificateRevoked</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(id, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, reason);</span></span></code></pre></div><p>The certificate stays. It is marked, with a timestamp and a public reason, and that is the strongest thing a chain can do.</p><p>This cuts both ways, and the tension is worth teaching rather than glossing:</p><ul><li><strong>It protects the holder.</strong> An issuer cannot quietly erase a certificate and claim it was never granted. The original issuance is permanent evidence.</li><li><strong>It exposes the holder.</strong> &quot;Revoked: academic misconduct&quot; is visible for ever, to everyone, with no appeal and no expiry. A university database can correct a mistake. A chain records the correction as another permanent entry.</li></ul><p>Real credential systems handle this with status lists and expiry rather than permanent public flags, precisely because a permanent public accusation is a serious thing to build.</p><p><strong>Anyone can issue.</strong> The contract checks the issuer is a resident, nothing more. Register an address, and you can issue &quot;PhD in Astrophysics&quot; to anyone.</p><p>That is correct behaviour, and it is the thing students must understand: the chain proves <em>who</em> issued a certificate and <em>that it has not changed</em>. It has no opinion on whether the issuer is credible. Credibility comes from outside — the verifier must recognise the issuer&#39;s address, exactly as they must recognise a university&#39;s letterhead today.</p><p>The chain solved integrity and timestamping. It did not solve authority, and no chain does.</p><h2 id="walk-through-it" tabindex="-1">Walk through it <a class="header-anchor" href="#walk-through-it" aria-label="Permalink to &quot;Walk through it&quot;">​</a></h2><ol><li>Write a short text file. This stands in for a transcript.</li><li>Issue a certificate to a classmate with the file&#39;s hash.</li><li><strong>Classmate:</strong> verify it — hash the file, look it up, confirm issuer and validity.</li><li>Change one character in the file. Hash again. Verify. It is not found.</li><li>Revoke the certificate with a reason.</li><li>Verify once more: the certificate is still there, now marked revoked.</li><li>Try to revoke someone else&#39;s certificate. <code>NotTheIssuer(issuer)</code>.</li></ol><h2 id="what-actually-happened-on-chain" tabindex="-1">What actually happened on chain <a class="header-anchor" href="#what-actually-happened-on-chain" aria-label="Permalink to &quot;What actually happened on chain&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CertificateIssued(id: 4, issuer: 0x…, holder: 0x…, course: &quot;CS 5590&quot;, docHash: 0x…)</span></span>
<span class="line"><span>Stamped(tokenId: …, moduleId: 7, by: certificateRegistry)</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>CertificateRevoked(id: 4, issuer: 0x…, reason: &quot;issued in error&quot;)</span></span></code></pre></div><p>Three of the four issue parameters are <code>indexed</code>, so a verifier can filter by issuer or by holder without scanning every log. <code>course</code> is not indexed — indexed strings are stored as hashes and become unreadable, which is a real trap: index what you filter by, leave readable what you display.</p><h2 id="when-a-plain-database-is-better" tabindex="-1">When a plain database is better <a class="header-anchor" href="#when-a-plain-database-is-better" aria-label="Permalink to &quot;When a plain database is better&quot;">​</a></h2><p>Inside one institution, always. The registry has the data, controls the process, and can correct mistakes — all properties a chain removes.</p><p>Anchoring earns its place when <strong>the verifier does not trust the issuer&#39;s database</strong>: cross border, years later, after a merger or a closure, or when the issuer has an incentive to revise history. Note that the chain does not have to be the only record — anchoring alongside a normal database gives you integrity proof without giving up the database&#39;s advantages, and that hybrid is what most serious deployments actually do.</p><h2 id="what-this-does-not-fix" tabindex="-1">What this does not fix <a class="header-anchor" href="#what-this-does-not-fix" aria-label="Permalink to &quot;What this does not fix&quot;">​</a></h2><ul><li><strong>Issuer authority.</strong> Anyone can issue anything. Recognising legitimate issuers is off-chain work.</li><li><strong>Privacy of the fact.</strong> The course name is on chain in clear text. &quot;CS 5590, revoked&quot; is public even though the transcript is not.</li><li><strong>Selective disclosure.</strong> Showing a certificate shows the whole thing, and links it to an address with a full transaction history.</li><li><strong>Lost documents.</strong> Lose the file and you cannot prove anything. The chain has the hash, not the content.</li></ul><h2 id="common-mistakes" tabindex="-1">Common mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common mistakes&quot;">​</a></h2><ul><li><strong>Putting the document on chain.</strong> Irreversible, public, and usually illegal for personal data.</li><li><strong>Hashing inconsistently.</strong> Text encoding, line endings, trailing whitespace. Pick the raw bytes and document it.</li><li><strong>Indexing the course string</strong>, then wondering why the explorer shows a hash.</li><li><strong>Overclaiming in the UI.</strong> &quot;✓ Verified&quot; invites the reader to believe the issuer is legitimate. &quot;Issued by 0x… on 3 March, not revoked&quot; is the honest version.</li><li><strong>No revocation at all.</strong> Very common in student projects, and it makes the system unusable in practice.</li></ul><h2 id="security-checklist" tabindex="-1">Security checklist <a class="header-anchor" href="#security-checklist" aria-label="Permalink to &quot;Security checklist&quot;">​</a></h2><ul><li>[ ] Can anyone but the issuer revoke?</li><li>[ ] Can a revoked certificate be un-revoked?</li><li>[ ] Can the same document be anchored twice, by different issuers?</li><li>[ ] What does the on-chain record leak about the holder?</li><li>[ ] If the issuer&#39;s key is stolen, what can the thief do — and how would anyone know?</li><li>[ ] Can a verifier distinguish a real issuer from a lookalike address?</li></ul><h2 id="extend-it" tabindex="-1">Extend it <a class="header-anchor" href="#extend-it" aria-label="Permalink to &quot;Extend it&quot;">​</a></h2><ol><li>Add expiry, so a certificate lapses rather than needing revocation. Then decide what <code>isValid</code> should say about an expired one.</li><li>Implement a <strong>status list</strong>: one bitmap covering thousands of certificates, so revocation costs one bit instead of one transaction. This is what the W3C standard actually does — work out why.</li><li>Add an issuer allowlist controlled by the DAO from module 12, and argue about who should be on it.</li></ol><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://www.w3.org/TR/vc-data-model-2.0/" target="_blank" rel="noreferrer">W3C Verifiable Credentials Data Model</a></li><li><a href="https://www.w3.org/TR/vc-bitstring-status-list/" target="_blank" rel="noreferrer">Bitstring Status List</a> — revocation at scale.</li><li>SD-JWT VC, for selective disclosure without zero-knowledge proofs.</li></ul><p><strong>Next:</strong> <a href="./08-event-tickets">Module 8 · Event tickets →</a></p>`,48)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
